/// Checks all collection size limits that are configured in strict mode.
async fn check_collection_size_limit(collection: &Collection, strict_mode_config: &StrictModeConfig) -> CollectionResult<()> {
    let vector_limit = strict_mode_config.max_collection_vector_size_bytes;
    let payload_limit = strict_mode_config.max_collection_payload_size_bytes;
    let point_limit = strict_mode_config.max_points_count;
    if (vector_limit, payload_limit, point_limit) == (None, None, None) { return Ok(()); }
    let Some(stats) = collection.estimated_collection_stats().await? else { return Ok(()); };
    if let Some(vector_storage_size_limit_bytes) = vector_limit { check_collection_vector_size_limit(vector_storage_size_limit_bytes, stats)?; }
    if let Some(payload_storage_size_limit_bytes) = payload_limit { check_collection_payload_size_limit(payload_storage_size_limit_bytes, stats)?; }
    if let Some(points_count_limit) = point_limit { check_collection_points_count_limit(points_count_limit, stats)?; }
    Ok(())
}
fn check_collection_points_count_limit(points_count_limit: usize, stats: &CollectionSizeAtomicStats) -> CollectionResult<()> {
    let points_count = stats.get_points_count();
    if points_count >= points_count_limit {
        return Err(CollectionError::bad_request(format!("Max points count limit of {points_count_limit} reached!")));
    }
    Ok(())
}

